M="pharm-cvs"
BOSS=dict(th="เคสใหญ่: เหนื่อยหอบขาบวม",en="Boss case: Breathless with swollen legs",
case="A 64-year-old man with prior MI has 3 months of exertional dyspnea, orthopnea and ankle edema. BP 128/78 mm Hg, HR 92, bibasal crackles, JVP raised. Echocardiogram: LVEF 30%. eGFR 60, K⁺ 4.3.",
qs=[
("Drug that relieves his congestion fastest:",["Loop diuretic (furosemide)","Cardiac glycoside (digoxin)","Dihydropyridine CCB (amlodipine)","Aldosterone antagonist (spironolactone)"],0,"Loops relieve symptoms but do not improve survival."),
("Which combination forms the core mortality-reducing therapy for HFrEF?",["ARNI + β-blocker + MRA + SGLT2 inhibitor","Loop diuretic + thiazide + digoxin + nitrate","Nitrate + amlodipine + loop diuretic + statin","Amiodarone + digoxin + loop diuretic + aspirin"],0,"The four pillars of guideline-directed medical therapy: ARNI (or ACEi/ARB), an evidence-based β-blocker, an MRA and an SGLT2 inhibitor."),
("Sacubitril works by:",["Blocking AT₁ receptors → ↓ aldosterone release","Inhibiting neprilysin → ↑ natriuretic peptides","Inhibiting Na⁺/K⁺-ATPase → ↑ intracellular Ca²⁺","Blocking mineralocorticoid receptors → natriuresis"],1,"Combined with valsartan; never with an ACE inhibitor (angioedema)."),
("Which β-blocker is NOT proven for HFrEF?",["Carvedilol","Metoprolol succinate","Bisoprolol","Atenolol"],3,"Only carvedilol, metoprolol succinate and bisoprolol reduce mortality."),
("A key lab to monitor after starting spironolactone:",["Serum K⁺","Serum Ca²⁺","Platelets","LFTs only"],0,"Hyperkalemia risk, especially with ACEi/ARNI and CKD."),
("If he remains symptomatic in sinus rhythm with EF ≤ 35%, digoxin can:",["Reduce mortality but not hospitalizations","Reduce hospitalizations but not mortality","Reverse LV remodeling and improve survival","Replace the need for loop diuretics"],1,"Digoxin improves symptoms and reduces admissions only."),
],pass_=4)
T={
"cvmap":[("Nitrates relax vascular smooth muscle through:",["↑cGMP via NO","↑cAMP via β₂","Blocking L-type Ca²⁺ channels","Opening K⁺ channels"],0,"NO activates guanylyl cyclase → cGMP → myosin light chain dephosphorylation."),
 ("Which class acts on the Na⁺/K⁺-ATPase?",["Digoxin","Ranolazine","Ivabradine","Hydralazine"],0,"Digoxin inhibits the pump → ↑ intracellular Na⁺ → ↑ Ca²⁺ via NCX."),
 ('A 67-year-old woman with HFrEF is started on a new drug. Two weeks later she has a persistent dry cough, and serum K⁺ has risen from 4.4 to 5.3 mEq/L. Which mechanism best explains her cough?', ['↑ Bradykinin from blocked kininase II', '↑ Aldosterone from renin escape', '↑ Natriuretic peptide from neprilysin block', '↑ Histamine release from mast cells'], 0, 'ACE (kininase II) inhibition raises bradykinin, causing cough and angioedema; hyperkalemia follows ↓ aldosterone. Neprilysin inhibitors are combined with ARBs, not used alone.', 3)],
"htn":[("First-line agent for hypertension in a patient with diabetes and albuminuria:",["ACE inhibitor or ARB","Hydralazine or minoxidil","β-blocker such as atenolol","Clonidine or methyldopa"],0,"ACEi/ARB slow diabetic nephropathy."),
 ("Safe antihypertensives in pregnancy:",["Labetalol, nifedipine, methyldopa","Lisinopril, enalapril, captopril","Losartan, valsartan, candesartan","Aliskiren, lisinopril, losartan"],0,"Hydralazine is also used. RAAS inhibitors (ACEi, ARB, aliskiren) are teratogenic (renal dysgenesis)."),
 ('A 46-year-old man is started on hydrochlorothiazide for blood pressure of 156/96 mm Hg. Six weeks later he wakes with an exquisitely painful, red, swollen first metatarsophalangeal joint; serum urate is 9.8 mg/dL. How did the drug most likely precipitate this?', ['↓ Renal uric acid excretion', '↑ De novo purine synthesis', '↑ Cell turnover releasing purines', 'Inhibition of xanthine oxidase'], 0, 'Thiazides cause volume contraction and compete for tubular urate secretion, raising serum urate. Xanthine oxidase inhibition would lower urate (allopurinol).', 3)],
"ccb":[("Which CCB class mainly acts on vascular smooth muscle?",["Dihydropyridines (amlodipine)","Phenylalkylamines (verapamil)","Benzothiazepines (diltiazem)","Non-dihydropyridines as a group"],0,"Non-dihydropyridines act more on the heart (↓ HR, ↓ AV conduction)."),
 ("A common adverse effect of dihydropyridine CCBs:",["Peripheral edema","Hyperkalemia","Dry cough","Marked bradycardia"],0,"Also flushing, headache, gingival hyperplasia; verapamil causes constipation."),
 ('A 69-year-old man with hypertension and stable angina is started on a new drug. Three weeks later he reports constipation; HR is 54/min and the ECG shows a PR interval of 0.24 s. Which drug was most likely started?', ['Verapamil', 'Amlodipine', 'Nifedipine', 'Hydralazine'], 0, 'Verapamil (non-dihydropyridine) slows SA/AV nodal conduction and causes constipation. Dihydropyridines cause reflex tachycardia and edema rather than AV block.', 2)],
"vasodil":[("Hydralazine adverse effect:",["Drug-induced lupus","Hypertrichosis only","Cough","Gynecomastia"],0,"Also reflex tachycardia; co-give a β-blocker. Used in pregnancy."),
 ("Minoxidil causes:",["Hypertrichosis","Lupus","Hyperkalemia","Bradycardia"],0,"K⁺ channel opener in arterioles; reflex tachycardia and fluid retention."),
 ('A 41-year-old woman treated for months with an arteriolar vasodilator for hypertension develops arthralgias, a malar rash and pleuritic chest pain. ANA and anti-histone antibodies are positive; anti-dsDNA is negative. Which patient factor most increased her risk?', ['Slow hepatic N-acetylation', 'Rapid hepatic N-acetylation', 'Poor CYP2D6 metabolism', 'Low TPMT enzyme activity'], 0, 'Hydralazine-induced lupus is more common in slow acetylators, who keep higher drug levels. TPMT deficiency predisposes to azathioprine/6-MP toxicity, not drug-induced lupus.', 3)],
"htnemerg":[("Which drug is used in hypertensive emergency and can cause cyanide toxicity?",["Nitroprusside","Labetalol","Clevidipine","Fenoldopam"],0,"Short acting; ↑cGMP via direct NO release."),
 ("Fenoldopam is:",["A selective D₁ agonist","A selective α₁ blocker","A dihydropyridine CCB","An NO-donor nitrate"],0,"Dilates renal vessels and promotes natriuresis; useful in hypertensive emergency with renal concerns."),
 ('A 58-year-old man has sudden tearing chest pain radiating to the back. BP is 210/120 mm Hg in the right arm and 170/100 mm Hg in the left, HR 108/min; CT angiography shows a type B aortic dissection. Which IV drug should be given first?', ['Labetalol', 'Hydralazine', 'Nicardipine', 'Fenoldopam'], 0, 'In aortic dissection, β-blockade (labetalol or esmolol) comes first to lower HR and dP/dt. Pure vasodilators given alone cause reflex tachycardia and increase shear stress.', 3)],
"nitrates":[("Nitrates relieve angina mainly by:",["Venodilation → ↓ preload","Arteriolar dilation only","↑ contractility","↓ heart rate"],0,"Reduced preload lowers myocardial O₂ demand."),
 ("Nitrates are contraindicated with:",["PDE5 inhibitors (sildenafil)","Low-dose aspirin (COX inhibitor)","Statins (atorvastatin)","β-blockers (metoprolol)"],0,"Severe hypotension. Tolerance develops; need a nitrate-free interval."),
 ('A 63-year-old man with stable angina has taken isosorbide dinitrate every 6 hours around the clock for 3 months. His angina, initially well controlled, has returned at the same dose. Which change is most appropriate?', ['Add a daily nitrate-free interval', 'Shorten the dosing to every 4 hours', 'Switch to a 24-hour nitrate patch', 'Add immediate-release nifedipine'], 0, 'Continuous exposure causes nitrate tolerance; an 8–12 h nitrate-free interval restores efficacy. A 24-hour patch maintains exposure and worsens tolerance.', 3)],
"antianginal":[("Ranolazine works by:",["Inhibiting late Na⁺ current","Blocking β₁ receptors in the SA node","Opening ATP-sensitive K⁺ channels","Blocking the If current in the SA node"],0,"↓ diastolic wall tension; may prolong QT."),
 ("Ivabradine lowers heart rate by:",["Blocking the If (funny) current in the SA node","Blocking β₁ receptors in the SA node","Blocking L-type Ca²⁺ channels in the AV node","Increasing vagal tone via M₂ receptors"],0,"Used in HFrEF with HR ≥ 70 on maximal β-blocker; may cause luminous phenomena."),
 ('A 66-year-old man has persistent exertional angina despite maximal metoprolol and amlodipine. Resting HR is 52/min and BP 102/64 mm Hg. A drug is added that reduces angina without lowering HR or BP. What is its mechanism?', ['Inhibition of late inward Na⁺ current', 'Blockade of the If current in SA node', 'Blockade of L-type Ca²⁺ channels', 'Release of NO in venous smooth muscle'], 0, 'Ranolazine inhibits the late Na⁺ current, reducing Ca²⁺ overload and diastolic wall tension without hemodynamic effects. Ivabradine (If block) would further lower an already slow HR.', 3)],
"hf":[("Which diuretic class reduces mortality in HFrEF?",["Mineralocorticoid receptor antagonists","Loop diuretics (furosemide, torsemide)","Thiazide-like diuretics","Carbonic anhydrase inhibitors"],0,"Spironolactone and eplerenone improve survival."),
 ("Hydralazine plus isosorbide dinitrate is especially beneficial in:",["Self-identified Black patients with HFrEF","Patients with HFpEF and atrial fibrillation","Hypertrophic obstructive cardiomyopathy","Severe symptomatic aortic stenosis"],0,"Also used when ACEi/ARB/ARNI are not tolerated."),
 ('A 63-year-old man with HFrEF (EF 30%) takes lisinopril, metoprolol succinate, furosemide and spironolactone. He develops painful bilateral breast enlargement. Which drug is the most appropriate substitute to keep the mortality benefit?', ['Eplerenone', 'Amiloride', 'Triamterene', 'Chlorthalidone'], 0, "Spironolactone's antiandrogen effect causes gynecomastia; eplerenone is a more selective MRA that also reduces HFrEF mortality. Amiloride spares K⁺ but has no proven HF mortality benefit.", 3)],
"digoxin":[("Digoxin toxicity is promoted by:",["Hypokalemia","Hyperkalemia","Hypercalcemia only","High-salt diet"],0,"Low K⁺ increases digoxin binding to the pump; also renal failure and verapamil, amiodarone, quinidine."),
 ("Classic ECG/vision signs of digoxin toxicity:",["Scooped ST, yellow-tinted vision, arrhythmias","QT prolongation, blue-tinged vision, torsades","Delta waves, short PR interval, wide QRS","Osborn J waves, bradycardia, shivering"],0,"Nausea, blurry yellow vision, AV block; worse with renal failure and hypokalemia."),
 ('A 76-year-old woman with HFrEF and atrial fibrillation has a ventricular rate of 118/min and BP 92/58 mm Hg. A drug is added that increases contractility and also slows the ventricular rate. By which mechanism does it slow AV conduction?', ['↑ Vagal tone at the AV node', 'β₁ blockade at the AV node', 'L-type Ca²⁺ block in the AV node', 'K⁺ channel block in nodal tissue'], 0, "Digoxin's parasympathomimetic (vagal) effect slows AV nodal conduction; its inotropy comes from Na⁺/K⁺-ATPase inhibition. β-blockers and CCBs would lower BP and contractility further.", 3)],
"statins":[("Statins inhibit:",["HMG-CoA reductase","Squalene synthase","NPC1L1","PCSK9"],0,"↓ hepatic cholesterol → ↑ LDL receptors → ↓ LDL."),
 ("Statin adverse effects:",["Myopathy and ↑ LFTs","Flushing and pruritus","Cholesterol gallstones","Hyperuricemia and gout"],0,"Myopathy risk rises with fibrates, niacin and CYP3A4 inhibitors."),
 ('A 52-year-old woman with LDL 182 mg/dL is started on a drug that inhibits the rate-limiting step of cholesterol synthesis. Eight weeks later her LDL is 96 mg/dL. Which change chiefly accounts for the fall in plasma LDL?', ['↑ Hepatic LDL-receptor expression', '↓ Intestinal cholesterol absorption', '↑ Endothelial lipoprotein lipase', '↓ Hepatic bile acid secretion'], 0, 'Statins lower hepatocyte cholesterol, activating SREBP-2 to upregulate LDL receptors that clear LDL. Reduced intestinal absorption is the mechanism of ezetimibe.', 3)],
"nonstatin":[("Ezetimibe acts by:",["Blocking intestinal NPC1L1","Inhibiting HMG-CoA reductase","Binding intestinal bile acids","Activating PPAR-α"],0,"Blocks cholesterol absorption at the brush border → lowers LDL; well tolerated."),
 ("Bile acid resins (cholestyramine) can:",["Raise serum triglycerides","Markedly lower triglycerides","Cause prostaglandin flushing","Cause hyperuricemia and gout"],0,"Also impair absorption of other drugs and fat-soluble vitamins; GI upset."),
 ('A 42-year-old man with familial hypercholesterolemia has tendon xanthomas and LDL 190 mg/dL despite maximal atorvastatin plus ezetimibe. He starts a subcutaneous monoclonal antibody every 2 weeks. What is its mechanism?', ['Prevents LDL-receptor degradation', 'Blocks intestinal NPC1L1 transport', 'Inhibits hepatic ATP-citrate lyase', 'Inhibits MTP to block VLDL assembly'], 0, "PCSK9 inhibitors (evolocumab, alirocumab) stop PCSK9 from targeting LDL receptors for lysosomal degradation. NPC1L1 is ezetimibe's target, already on board.", 3)],
"tg":[("Fibrates act on:",["PPAR-α → ↑ lipoprotein lipase","HMG-CoA reductase → ↑ LDL receptors","NPC1L1 → ↓ gut cholesterol uptake","PCSK9 (blocked) → ↑ LDL receptors"],0,"Best for lowering TG; risk of gallstones and myopathy with statins."),
 ("Niacin-induced flushing is reduced by:",["Aspirin (NSAID) beforehand","Statin taken at bedtime","Fibrate taken with meals","Ezetimibe taken beforehand"],0,"Prostaglandin-mediated; niacin can also cause hyperglycemia and hyperuricemia."),
 ('A 47-year-old man with poorly controlled diabetes was admitted last month for acute pancreatitis. Fasting triglycerides are 1,150 mg/dL; LDL is 110 mg/dL. Which drug is most appropriate to lower his risk of recurrence?', ['Fenofibrate', 'Ezetimibe', 'Colesevelam', 'Evolocumab'], 0, 'Fibrates (PPAR-α → ↑ lipoprotein lipase) are the most effective TG-lowering drugs. Bile acid resins such as colesevelam can raise triglycerides.', 2)],
"class1":[("Which class I agent is used for ventricular arrhythmias after MI?",["Lidocaine (IB)","Flecainide (IC)","Quinidine (IA)","Propafenone (IC)"],0,"IB preferentially affects ischemic/depolarized tissue."),
 ("Class IC drugs are contraindicated in:",["Structural heart disease and post-MI","Supraventricular tachycardia without structural disease","Atrial fibrillation in healthy hearts","WPW"],0,"CAST trial: ↑ mortality after MI."),
 ('A 64-year-old man is treated with a class IA antiarrhythmic for atrial fibrillation. Two weeks later he has tinnitus, headache, blurred vision and diarrhea, and his QTc has lengthened. Which drug is he most likely taking?', ['Quinidine', 'Lidocaine', 'Flecainide', 'Procainamide'], 0, 'Cinchonism (tinnitus, headache, visual and GI upset) is characteristic of quinidine. Procainamide is also class IA but is known for drug-induced lupus, not cinchonism.', 2)],
"class2":[("β-blockers slow conduction mainly at the:",["AV node (nodal tissue)","Purkinje fibers (fast tissue)","Ventricular myocardium","Accessory pathway (bundle of Kent)"],0,"↓ Phase 4 slope and ↑ PR interval in nodal tissue. Esmolol is very short acting; metoprolol is used for rate control."),
 ("Caution with β-blockers in:",["Asthma and decompensated HF","Stable angina and prior MI","Migraine and essential tremor","Hypertension and thyrotoxicosis"],0,"Nonselective agents worsen bronchospasm; may mask hypoglycemia."),
 ('A 60-year-old man with type 1 diabetes starts propranolol after a myocardial infarction. A week later he is found confused with capillary glucose 42 mg/dL and says he never felt shaky or had palpitations. Why were his warning symptoms absent?', ['Blunted β-adrenergic warning signs', 'Direct stimulation of insulin release', 'Inhibition of hepatic insulin clearance', '↑ Skeletal muscle glucose uptake'], 0, 'β-blockers mask adrenergic hypoglycemia symptoms (tremor, palpitations) and nonselective agents also blunt glycogenolysis. They do not stimulate insulin secretion.', 3)],
"class3":[("Amiodarone adverse effects include:",["Pulmonary fibrosis and thyroid dysfunction","Drug-induced lupus and agranulocytosis","Gingival hyperplasia and hirsutism","Cinchonism and thrombocytopenia"],0,"Also hepatotoxicity. Check PFTs, LFTs and TFTs; blue-gray skin and corneal deposits."),
 ("Class III agents prolong the action potential by blocking:",["K⁺ channels","Na⁺ channels","Ca²⁺ channels","β receptors"],0,"Prolong QT; sotalol and dofetilide carry torsades risk."),
 ('A 68-year-old man on long-term antiarrhythmic therapy has 3 months of dry cough and dyspnea with bibasal crackles; CT shows reticular opacities and DLCO is reduced. He also has blue-gray facial skin and TSH 11 mU/L. Which drug is most likely responsible?', ['Amiodarone', 'Sotalol', 'Dofetilide', 'Ibutilide'], 0, 'Amiodarone causes pulmonary fibrosis, thyroid dysfunction (iodine content) and blue-gray skin. Sotalol and dofetilide mainly cause QT prolongation/torsades.', 2)],
"class4":[("Adenosine is the drug of choice to terminate:",["Paroxysmal SVT","Ventricular tachycardia","Atrial flutter (as cure)","Torsades"],0,"Very short acting; causes flushing, chest pain; effect blocked by theophylline/caffeine."),
 ("Magnesium sulfate is used for:",["Torsades de pointes","SVT","Atrial fibrillation rate control","Sinus bradycardia"],0,"Also for digoxin-induced arrhythmias."),
 ("A 27-year-old woman has palpitations; HR is 186/min with a regular narrow-QRS tachycardia and BP 118/74 mm Hg. Vagal maneuvers fail. A rapid IV bolus causes brief flushing and chest tightness, then sinus rhythm returns. What is this drug's mechanism?", ['A₁ receptor → K⁺ efflux at AV node', 'Block of L-type Ca²⁺ at AV node', 'Block of β₁ receptors at AV node', 'Block of K⁺ channels → long ERP'], 0, 'Adenosine acts on A₁ (Gi) receptors, ↑ K⁺ efflux and ↓ Ca²⁺ current, transiently blocking the AV node. Verapamil blocks L-type Ca²⁺ channels and acts more slowly.', 3)],
"hfrx":[("SGLT2 inhibitors in HFrEF:",["Reduce HF admissions and CV death","Benefit only patients with diabetes","Are contraindicated once EF < 35%","Improve symptoms but not outcomes"],0,"Benefit is seen with or without diabetes. Dapagliflozin and empagliflozin are one of the four pillars."),
 ("Before starting an ARNI in a patient on an ACE inhibitor, stop the ACEi for:",["36 hours","1 week","No washout needed","24 days"],0,"To reduce angioedema risk."),
 ("A 59-year-old woman without diabetes has HFrEF (EF 32%) on sacubitril/valsartan, carvedilol and spironolactone. A fourth drug is added; two months later she develops vulvovaginal candidiasis. What is the added drug's mechanism?", ['Inhibits proximal Na⁺-glucose cotransport', 'Inhibits neprilysin in the kidney', 'Blocks the If current in the SA node', 'Blocks aldosterone in collecting duct'], 0, 'SGLT2 inhibitors (dapagliflozin, empagliflozin) cause glucosuria, predisposing to genital mycotic infections, and reduce HF death/admission even without diabetes. Neprilysin is already inhibited by sacubitril.', 3)],
}
